const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"leakStatus":"SECURE","transmissionLossPercentage":3.8,"estimatedLossLitersPerHour":120,"tankerQualityVerdict":"COMPLIANT","measuredTds":380,"measuredPh":7.2,"suspectedLeakZones":[],"actionPlan":["Sump-to-overhead transmission loss within acceptable 5% friction tolerance","Private tanker water meets BIS 10500 potable water quality limits"]} } }];
}
